# Auth0 Federated Login Flow
from authlib.integrations.flask_client import OAuth
import os

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY')

auth0 = OAuth(app)
auth0.register('auth0', {
    'client_id': os.environ['AUTH0_CLIENT_ID'],
    'client_secret': os.environ['AUTH0_CLIENT_SECRET'],
    'authorize_url': 'https://{domain}/authorize',
    'access_token_url': 'https://{domain}/oauth/token',
    'api_base_url': 'https://{domain}/userinfo',
    'client_kwargs': {'scope': 'openid profile email'}
}, domain=os.environ['AUTH0_DOMAIN'])

@app.route('/login')
def login():
    redirect_uri = url_for('authorize', _external=True)
    return auth0.create_session('auth0', redirect_uri)

@app.route('/authorize')
def authorize():
    token = auth0.authorize_access_token()
    return redirect(url_for('profile', _external=True))

@app.route('/profile')
def profile():
    try:
        userinfo = auth0.get('auth0')
        return f'User info: {userinfo.to_dict()}'
    except Auth0ConnectionError:
        return 'Failed to fetch userinfo'

if __name__ == '__main__':
    app.run(debug=True)
